import { recipe } from './detail-helpers-v1.js';
import { settlementTypes } from './economy-settlements.js';
const orderNotes='The quantity is checked against the order.|A written estimate is requested first.|The buyer supplies the reference sample.|Collection follows the next market day.|The keeper retains a copy of the request.|The dimensions must match the previous order.|A receipt is needed for the buyer.|The buyer confirms the collection time.|The order awaits a final specification.|The customer approves substitutions in advance.';
const enquiries='A repeat request from {customer} concerns {product}.|An estimate for {customer} covers {product}.|A reserved order for {customer} names {product}.|The collection list for {customer} includes {product}.|The current enquiry from {customer} concerns {product}.|A written request from {customer} specifies {product}.|An unfinished order for {customer} concerns {product}.|A sample request from {customer} names {product}.|The order book lists {product} for {customer}.|A scheduled collection by {customer} concerns {product}.';
