export const supplyRecipes=recipe(supplyNotes,restockNotes);
const requestNotes='asks about {product} at {displayName}|compares notes on {trade} work in {district}|checks an order for {product}|carries a sample for a {trade} commission|looks for a supplier of {material}|brings a message about {product}|checks a delivery through {supplyRoute}|asks who handles {trade} orders in {district}|compares an estimate for {product}|records a request for {product}';
export const guestRecipes=Object.fromEntries(Object.entries(settlementTypes).map(([key,p])=>[key,recipe(p.customers.map(c=>`A visitor representing ${c}`),requestNotes)]));
